def cantor_numbering(N: int) -> str:
    if N == 1:
        return "1/1"
    level = 1
    while N > (level * (level + 1)) // 2:
        N -= (level * (level + 1)) // 2
        level += 1
    if level % 2 == 0:
        numerator = N
        denominator = level + 1 - N
    else:
        numerator = level + 1 - N
        denominator = N
    return f"{numerator}/{denominator}"

