def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        total = 0
        for i, char in enumerate(isbn):
            if char == '-':
                continue
            digit = int(char) if char != 'X' else 10
            total += digit * (10 - i)
        return total % 11

    parts = isbn.split('-')
    if len(parts) != 4 or len(parts[2]) != 7:
        raise ValueError("Invalid ISBN format")

    calculated_checksum = calculate_checksum(isbn[:-1])
    expected_checksum = int(isbn[-1]) if isbn[-1] != 'X' else 10

    if calculated_checksum == expected_checksum:
        return "Right"
    else:
        corrected_isbn = isbn[:-1] + ('X' if calculated_checksum == 10 else str(11 - calculated_checksum))
        return corrected_isbn

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    row_counts = [0] * (M + 1)
    col_counts = [0] * (N + 1)

