def count_passing_ways(n: int, m: int) -> int:
    if m == 0:
        return 1
    if n == 1:
        return 1

    dp = [[0] * (m + 1) for _ in range(n)]
    dp[0][1] = 1
    dp[0][2] = 1

    for i in range(1, n):
        dp[i][1] = 2
        for j in range(2, m + 1):
            dp[i][j] = dp[i - 1][j - 1] + dp[i - 2][j - 1]

    return dp[n - 1][m]

