def max_energy(beads):
    n = len(beads)
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = (i + length - 1) % n
            for k in range(i, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[(k + 1) % n][j] + beads[i] * beads[k] * beads[j])

    return dp[0][(n - 1) % n]

