def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    queue = deque([(A, 0)])
    visited = set([A])

    while queue:
        current, steps = queue.popleft()

        if steps > 10:
            return "NO ANSWER!"

        if current == B:
            return steps

        for src, tgt in rules:
            start = 0
            while start < len(current):
                start = current.find(src, start)
                if start == -1:
                    break
                new_str = current[:start] + tgt + current[start + len(src):]
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start += 1

    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

