def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            for k in range(min(j, a[i - 1]) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    key = key.upper()
    ciphertext = ciphertext.upper()
    plaintext = []
    key_length = len(key)
    for i in range(len(ciphertext)):
        key_char = key[i % key_length]
        ciphertext_char = ciphertext[i]
        if ciphertext_char.isalpha():
            shift = ord(key_char) - ord('A')
            plaintext_char = chr((ord(ciphertext_char) - ord('A') - shift) % 26 + ord('A'))
            plaintext.append(plaintext_char)
        else:
            plaintext.append(ciphertext_char)
    return ''.join(plaintext).lower()

def mod_inverse(a, b):
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    gcd, x, _ = extended_gcd(a, b)
    if gcd != 1:
        return None
    else:
        return x % b

